import '../styles/cart.css';

function Cart() {
    const item1 = 15;
    const item2 = 20;
    const [quantite1, setQuantite1] = useState(0);
    return (
        <div className="cart">
            <h1>Cart</h1>
            <p>Item 1: {item1}€</p>
            <button onClick={() => setQuantite1(quantite1 + 1)}>Ajouter</button>
            <p>Item 2: {item2}€</p>
            <div className="cart-total">
                <p><b></b>Total: {item1 + item2}€</p>
            </div>
        </div>
    );
}
export default Cart;
